CREATE TABLE test1(id INTEGER PRIMARY KEY,a); CREATE TABLE test2(id INTEGER,b); CREATE VIEW test AS SELECT test1.id AS id,a AS a,b AS b FROM test1 JOIN test2 ON test2.id=test1.id; CREATE TRIGGER I_test INSTEAD OF INSERT ON test BEGIN INSERT INTO test1(id,a) VALUES(NEW.id,NEW.a); INSERT INTO test2(id,b) VALUES(NEW.id,NEW.b); END; CREATE TRIGGER U_test INSTEAD OF UPDATE ON test BEGIN UPDATE test1 SET a=NEW.a WHERE id=NEW.id; UPDATE test2 SET b=NEW.b WHERE id=NEW.id; END; INSERT INTO test VALUES(1,2,3); INSERT INTO test VALUES(4,5,6); UPDATE test1 SET a=22 WHERE id=1;